int isPalindrome(const char* str) {
    if (!str) return 0;
    int left = 0, right = 0;
    while (str[right]) right++;
    right--;
    while (left < right) {
        char c1 = str[left], c2 = str[right];
        if (c1 >= 'A' && c1 <= 'Z') c1 += 32;
        if (c2 >= 'A' && c2 <= 'Z') c2 += 32;
        if (c1 != c2) return 0;
        left++; right--;
    }
    return 1;
}

void reverseString(char* str) {
    if (!str) return;
    int len = 0;
    while (str[len]) len++;
    int left = 0, right = len - 1;
    while (left < right) {
        char t = str[left];
        str[left] = str[right];
        str[right] = t;
        left++; right--;
    }
}

