void* safeMalloc(size_t size) {
    if (size == 0) return NULL;
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Out of memory!\n");
        exit(1);
    }
    return ptr;
}

void* safeCalloc(size_t count, size_t size) {
    if (count == 0 || size == 0) return NULL;
    void* ptr = calloc(count, size);
    if (!ptr) {
        fprintf(stderr, "Out of memory in calloc!\n");
        exit(1);
    }
    return ptr;
}

void safeFree(void** ptr) {
    if (ptr && *ptr) {
        free(*ptr);
        *ptr = NULL;
    }
}

int** allocate2DArray(int rows, int cols) {
    if (rows <= 0 || cols <= 0) return NULL;
    int** matrix = (int**)malloc(rows * sizeof(int*));
    if (!matrix) return NULL;
    matrix[0] = (int*)calloc(rows * cols, sizeof(int));
    if (!matrix[0]) { free(matrix); return NULL; }
    for (int i = 1; i < rows; i++) matrix[i] = matrix[0] + i * cols;
    return matrix;
}

void free2DArray(int** matrix) {
    if (matrix) {
        if (matrix[0]) free(matrix[0]);
        free(matrix);
    }
}

