char* readFileContents(const char* filePath, size_t* outLength) {
    if (!filePath) return NULL;
    FILE* fp = fopen(filePath, "rb");
    if (!fp) return NULL;
    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    if (size < 0) { fclose(fp); return NULL; }
    char* buffer = (char*)malloc(size + 1);
    if (!buffer) { fclose(fp); return NULL; }
    size_t read = fread(buffer, 1, size, fp);
    buffer[read] = '\0';
    fclose(fp);
    if (outLength) *outLength = read;
    return buffer;
}

int writeFileContents(const char* filePath, const char* content) {
    if (!filePath || !content) return 0;
    FILE* fp = fopen(filePath, "wb");
    if (!fp) return 0;
    size_t len = strlen(content);
    size_t written = fwrite(content, 1, len, fp);
    fclose(fp);
    return written == len;
}

