typedef struct ArrayStack {
    int* items;
    int top;
    int capacity;
} ArrayStack;

ArrayStack* createStack(int capacity) {
    ArrayStack* s = (ArrayStack*)malloc(sizeof(ArrayStack));
    if (!s) return NULL;
    s->capacity = capacity;
    s->top = -1;
    s->items = (int*)malloc(capacity * sizeof(int));
    return s;
}

int push(ArrayStack* stack, int value) {
    if (!stack || stack->top >= stack->capacity - 1) return 0;
    stack->items[++stack->top] = value;
    return 1;
}

int pop(ArrayStack* stack, int* outVal) {
    if (!stack || stack->top < 0) return 0;
    if (outVal) *outVal = stack->items[stack->top];
    stack->top--;
    return 1;
}

int peek(const ArrayStack* stack, int* outVal) {
    if (!stack || stack->top < 0) return 0;
    if (outVal) *outVal = stack->items[stack->top];
    return 1;
}

