typedef struct ArrayQueue {
    int* items;
    int front;
    int rear;
    int size;
    int capacity;
} ArrayQueue;

ArrayQueue* createQueue(int capacity) {
    ArrayQueue* q = (ArrayQueue*)malloc(sizeof(ArrayQueue));
    if (!q) return NULL;
    q->capacity = capacity;
    q->front = 0;
    q->size = 0;
    q->rear = capacity - 1;
    q->items = (int*)malloc(capacity * sizeof(int));
    return q;
}

int enqueue(ArrayQueue* q, int item) {
    if (!q || q->size == q->capacity) return 0;
    q->rear = (q->rear + 1) % q->capacity;
    q->items[q->rear] = item;
    q->size++;
    return 1;
}

int dequeue(ArrayQueue* q, int* outVal) {
    if (!q || q->size == 0) return 0;
    if (outVal) *outVal = q->items[q->front];
    q->front = (q->front + 1) % q->capacity;
    q->size--;
    return 1;
}

