} AVLNode;

AVLNode* rightRotate(AVLNode* y) {
    AVLNode* x = y->left;
    AVLNode* T2 = x->right;
    x->right = y;
    y->left = T2;
    int yl = y->left ? y->left->height : 0;
    int yr = y->right ? y->right->height : 0;
    y->height = 1 + ((yl > yr) ? yl : yr);
    int xl = x->left ? x->left->height : 0;
    int xr = x->right ? x->right->height : 0;
    x->height = 1 + ((xl > xr) ? xl : xr);
    return x;
}

AVLNode* leftRotate(AVLNode* x) {
    AVLNode* y = x->right;
    AVLNode* T2 = y->left;
    y->left = x;
    x->right = T2;
    int xl = x->left ? x->left->height : 0;
    int xr = x->right ? x->right->height : 0;
    x->height = 1 + ((xl > xr) ? xl : xr);
    int yl = y->left ? y->left->height : 0;
    int yr = y->right ? y->right->height : 0;
    y->height = 1 + ((yl > yr) ? yl : yr);
    return y;
}

