typedef struct GraphAdjNode {
    int dest;
    int weight;
    struct GraphAdjNode* next;
} GraphAdjNode;

typedef struct GraphAdjList {
    int numVertices;
    GraphAdjNode** adjLists;
} GraphAdjList;

GraphAdjList* createGraph(int vertices) {
    GraphAdjList* g = (GraphAdjList*)malloc(sizeof(GraphAdjList));
    if (!g) return NULL;
    g->numVertices = vertices;
    g->adjLists = (GraphAdjNode**)calloc(vertices, sizeof(GraphAdjNode*));
    return g;
}

void addEdge(GraphAdjList* g, int src, int dest, int weight) {
    if (!g || src >= g->numVertices || dest >= g->numVertices) return;
    GraphAdjNode* node = (GraphAdjNode*)malloc(sizeof(GraphAdjNode));
    if (!node) return;
    node->dest = dest;
    node->weight = weight;
    node->next = g->adjLists[src];
    g->adjLists[src] = node;
}

void bfs(const GraphAdjList* g, int startVertex) {
    if (!g || startVertex >= g->numVertices) return;
    int* visited = (int*)calloc(g->numVertices, sizeof(int));
    int* queue = (int*)malloc(g->numVertices * sizeof(int));
    int front = 0, rear = 0;
    visited[startVertex] = 1;
    queue[rear++] = startVertex;
    while (front < rear) {
        int curr = queue[front++];
        printf("%d ", curr);
        GraphAdjNode* temp = g->adjLists[curr];
        while (temp) {
            if (!visited[temp->dest]) {
                visited[temp->dest] = 1;
                queue[rear++] = temp->dest;
            }
            temp = temp->next;
        }
    }
    free(visited); free(queue);
}

void dijkstra(const GraphAdjList* g, int startVertex, int dist[]) {
    if (!g || !dist) return;
    int* visited = (int*)calloc(g->numVertices, sizeof(int));
    for (int i = 0; i < g->numVertices; i++) dist[i] = 2147483647;
    dist[startVertex] = 0;
    for (int count = 0; count < g->numVertices - 1; count++) {
        int minD = 2147483647, u = -1;
        for (int v = 0; v < g->numVertices; v++) {
            if (!visited[v] && dist[v] <= minD) {
                minD = dist[v]; u = v;
            }
        }
        if (u == -1) break;
        visited[u] = 1;
        GraphAdjNode* n = g->adjLists[u];
        while (n) {
            if (!visited[n->dest] && dist[u] != 2147483647 && dist[u] + n->weight < dist[n->dest]) {
                dist[n->dest] = dist[u] + n->weight;
            }
            n = n->next;
        }
    }
    free(visited);
}

