int isSafeQueen(int board[20][20], int row, int col, int n) {
    for (int i = 0; i < col; i++) if (board[row][i]) return 0;
    for (int i = row, j = col; i >= 0 && j >= 0; i--, j--) if (board[i][j]) return 0;
    for (int i = row, j = col; j >= 0 && i < n; i++, j--) if (board[i][j]) return 0;
    return 1;
}

int nQueens(int board[20][20], int col, int n) {
    if (col >= n) return 1;
    for (int i = 0; i < n; i++) {
        if (isSafeQueen(board, i, col, n)) {
            board[i][col] = 1;
            if (nQueens(board, col + 1, n)) return 1;
            board[i][col] = 0;
        }
    }
    return 0;
}

