double bisectionMethod(double (*f)(double), double a, double b, double tol) {
    if (f(a) * f(b) >= 0) return 0.0;
    double c = a;
    while ((b - a) >= tol) {
        c = (a + b) / 2.0;
        if (f(c) == 0.0) break;
        if (f(c) * f(a) < 0) b = c;
        else a = c;
    }
    return c;
}

double newtonRaphson(double (*f)(double), double (*df)(double), double x0, double tol, int maxIter) {
    double x = x0;
    for (int i = 0; i < maxIter; i++) {
        double y = f(x);
        double dy = df(x);
        if (dy == 0.0) break;
        double nextX = x - y / dy;
        if (fabs(nextX - x) < tol) return nextX;
        x = nextX;
    }
    return x;
}

double simpsonsRule(double (*f)(double), double a, double b, int n) {
    if (n % 2 != 0) n++;
    double h = (b - a) / n;
    double sum = f(a) + f(b);
    for (int i = 1; i < n; i++) {
        double x = a + i * h;
        sum += (i % 2 == 0) ? 2 * f(x) : 4 * f(x);
    }
    return (h / 3.0) * sum;
}

